mapper.select:
SELECT a.appointment_number AS appointmentNumber , a.member_number AS memberNumber , m.member_name AS patientName , m.member_phone_number AS phone , SUBSTR(m.resident_registration_number, 1, 6) AS birthDate , a.attending_physician AS doctorNumber , dm.member_name AS doctorName , TO_CHAR(a.reservation_start_date, 'YYYY-MM-DD') AS reserveDate , TO_CHAR(a.reservation_start_date, 'HH24:MI') AS reserveTime , TO_CHAR(a.reservation_start_date, 'YYYY-MM-DD"T"HH24:MI:SS') AS startAt , TO_CHAR(NVL(a.reservation_end_date, a.reservation_start_date + 30/1440) , 'YYYY-MM-DD"T"HH24:MI:SS') AS endAt , a.reservation_status AS status , a.symptoms AS symptoms , NVL(a.color, '#3788d8') AS color FROM appointment a INNER JOIN member m ON m.member_number = a.member_number LEFT JOIN member dm ON dm.member_number = a.attending_physician WHERE a.reservation_start_date IS NOT NULL AND a.reservation_status = '예약확정' AND a.reservation_start_date >= TO_DATE(#{fromDate}, 'YYYY-MM-DD') AND a.reservation_start_date < TO_DATE(#{toDate}, 'YYYY-MM-DD') + 1
AND a.attending_physician = #{doctorNumber}
ORDER BY a.reservation_start_date

        SELECT COUNT(*)
	      FROM APPOINTMENT
	     WHERE MEMBER_NUMBER = #{memberNumber}
	       AND ATTENDING_PHYSICIAN = #{doctorNumber}
	       AND RESERVATION_STATUS = '예약확정'
	       AND TRUNC(RESERVATION_START_DATE)
	             = TRUNC(TO_DATE(#{reserveAt}, 'YYYY-MM-DD HH24:MI'))

	       AND appointment_number != #{excludeNo}

mapper.insert:

    		SELECT 'A' || LPAD(SEQ_APPOINTMENT.NEXTVAL, 4, '0') FROM DUAL

    	INSERT INTO appointment (
		      appointment_number
		    , member_number
		    , reservation_start_date
		    , reservation_end_date
		    , reservation_status
		    , attending_physician
		    , symptoms
		    , color
		) VALUES (
		    #{appointmentNumber}
		  , #{memberNumber}
		  , TO_DATE(#{reserveAt}, 'YYYY-MM-DD HH24:MI')
		  , TO_DATE(#{reserveAt}, 'YYYY-MM-DD HH24:MI') + #{durationMinutes}/1440
		  , '예약확정'
		  , #{doctorNumber}
		  , #{symptoms}
		  , #{color}
		)

mapper.update:
	UPDATE APPOINTMENT
       SET RESERVATION_START_DATE = TO_DATE(#{reserveAt}, 'YYYY-MM-DD HH24:MI')
         , RESERVATION_END_DATE   = TO_DATE(#{reserveAt}, 'YYYY-MM-DD HH24:MI') + #{durationMinutes}/1440
         , ATTENDING_PHYSICIAN    = #{doctorNumber}
         , SYMPTOMS               = #{symptoms, jdbcType=VARCHAR}
     WHERE APPOINTMENT_NUMBER = #{appointmentNumber}
       AND RESERVATION_STATUS = '예약확정'
